// Linkifier for plain-text social feed posts.
//
// Turns @mentions, #hashtags and bare http(s) URLs into anchors.
// Everything else is HTML-escaped exactly once. Emails are never
// mistaken for mentions; URLs keep balanced trailing parentheses
// and drop other trailing punctuation.

const ESCAPES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

// Alternation order matters:
//   1. URLs (so @/# inside a URL are not re-tokenized)
//   2. emails (consumed whole, so user@example.com never yields a mention)
//   3. mentions, guarded by lookbehind (no word/dot just before the @)
//   4. hashtags (#a#b works because each match consumes its own text)
const TOKEN =
  /(https?:\/\/[^\s<>]+)|(?:[A-Za-z0-9._%+-]+)@(?:[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+))+|(?<![A-Za-z0-9._%+-])@([A-Za-z0-9_]+)|(?<![A-Za-z0-9_])#([A-Za-z0-9_]+)/g;

// Strip trailing punctuation from a matched URL. Commas etc. are always
// stripped; a closing paren is stripped only when it is not balanced by
// an opening paren inside the URL itself (wikipedia-style URLs survive).
function cleanUrl(raw) {
  let u = raw;
  while (u.length > 0) {
    const last = u[u.length - 1];
    if (/[.,;:!?'"]/.test(last)) {
      u = u.slice(0, -1);
      continue;
    }
    if (last === ')') {
      const opens = (u.match(/\(/g) || []).length;
      const closes = (u.match(/\)/g) || []).length;
      if (closes > opens) {
        u = u.slice(0, -1);
        continue;
      }
    }
    break;
  }
  return u;
}

const MAX_DISPLAY = 40;
const MIDLINE_ELLIPSIS = '\u22EF'; // midline horizontal ellipsis

function urlDisplay(url) {
  return url.length > MAX_DISPLAY
    ? url.slice(0, MAX_DISPLAY) + MIDLINE_ELLISIS_FALLBACK()
    : url;
}

function MIDLINE_ELLIPSIS_FALLBACK() {
  return MIDLINE_ELLIPSIS;
}

export function linkify(text, { mentionBase = '/', tagBase = '/' } = {}) {
  let out = '';
  let pos = 0;

  TOKEN.lastIndex = 0;
  for (let m = TOKEN.exec(text); m !== null; m = TOKEN.exec(text)) {
    out += escapeHtml(text.slice(pos, m.index));

    if (m[0].startsWith('http://') || m[0].startsWith('https://')) {
      const url = cleanUrl(m[0]);
      const display =
        url.length > MAX_DISPLAY ? url.slice(0, MAX_DISPLAY) + MIDLINE_ELLIPSIS : url;
      out += `<a href="${escapeHtml(url)}">${escapeHtml(display)}</a>`;
      pos = m.index + m[0].length;
    } else if (m[1] !== undefined) {
      // mention (group 1); group 0 was an email only if group 1 undefined,
      // handled below by falling through without emitting a link
      const name = m[1];
      out += `<a href="${escapeHtml(
        mentionBase + encodeURIComponent(name)
      )}">@${escapeHtml(name)}</a>`;
      pos = m.index + m[0].length;
    } else if (m[2] !== undefined) {
      const tag = m[2];
      out += `<a href="${escapeHtml(
        tagBase + encodeURIComponent(tag)
      )}>#${escapeHtml(tag)}</a>`;
      pos = m.index + m[0].length;
    } else {
      // plain email address: leave as escaped text, no anchor
      pos = m.index + m[0].length;
    }
  }
  out += escapeHtml(text.slice(pos));
  return out;
}

