import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { linkify } from '../src/linkify.js';

const $ = (html) => cheerio.load(html);

const opts = {
  mentionBase: 'https://social.example/',
  tagBase: 'https://social.example/tag/',
};

describe('mentions', () => {
  it('links a leading mention', () => {
    const html = linkify('hi @bob!', opts);
    expect($('a', html).length).toBe(1);
    expect($('a', html).attr('href')).toBe('https://social.example/bob');
    expect($('a', html).text()).toBe('@bob');
    expect(html.endsWith('!')).toBe(true);
  });

  it('an email address must NOT become a mention', () => {
    const html = linkify('mail me at bob.smith@example.co.uk ok', opts);
    expect($('a', html).length).toBe(0);
    expect(html).toContain('bob.smith@example.co.uk');
  });

  it('word characters before @ block a mention', () => {
    const html = linkify('foo@bar is not a mention', opts);
    expect($('a', html).length).toBe(0);
  });
});

describe('hashtags', () => {
  it('links a hashtag', () => {
    const html = linkify('loving #rustlang today', opts);
    const $a = $('a', html);
    expect($a.length).toBe(1);
    expect($a.attr('href')).toBe('https://social.example/tag/rustlang');
    expect($a.text()).toBe('#rustlang');
  });

  it('adjacent tokens #a#b both link', () => {
    const html = linkify('#a#b', opts);
    const hrefs = $('a', html)
      .toArray()
      .map((el) => $(el).attr('href'));
    expect(hrefs).toEqual([
      'https://social.example/tag/a',
      'https://social.example/tag/b',
    ]);
    expect(html).not.toContain('#');
  });
});

describe('URLs', () => {
  it('links a plain https URL', () => {
    const html = linkify('see https://example.com/page now', opts);
    const $a = $('a', html);
    expect($a.length).toBe(1);
    expect($a.attr('href')).toBe('https://example.com/page');
    expect($a.text()).toBe('https://example.com/page');
  });

  it('trailing comma is excluded from the URL', () => {
    const html = linkify('go to https://example.com/a,b, ok?', opts);
    const $a = $('a', html);
    expect($a.attr('href')).toBe('https://example.com/a,b');
    // the trailing ", ok?" stays as escaped text
    expect(html.endsWith(', ok?')).toBe(true);
  });

  it('balanced parens are kept (wikipedia-style URL)', () => {
    const url = 'https://en.wikipedia.org/wiki/Link_(hyphenation)';
    const html = linkify(`read ${url} today`, opts);
    const $a = $('a', html);
    expect($a.length).toBe(1);
    expect($a.attr('href')).toBe(url);
    expect($a.text()).toBe(url);
  });

  it('unbalanced closing paren is excluded from the URL', () => {
    const html = linkify('(see https://example.com/wiki/Thing) end', opts);
    const $a = $('a', html);
    expect($a.length).toBe(1);
    expect($a.attr('href')).toBe('https://example.com/wiki/Thing');
    // surrounding parens remain as literal text
    expect(html.startsWith('(see <a')).toBe(true);
    expect(html.endsWith(') end')).toBe(true);
  });

  it('long URL display text is trimmed to 40 chars + midline ellipsis', () => {
    const long =
      'https://example.com/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
    const html = linkify(long, opts);
    const $a = $('a', html);
    expect($a.attr('href')).toBe(long);
    expect($a.text()).toBe(long.slice(0, 40) + '\u22EF');
    expect($a.text().length).toBe(41);
  });
});

describe('escaping and mixed content', () => {
  it('angle brackets around a URL stay escaped and do not leak into markup', () => {
    const html = linkify('<https://example.com/x>', opts);
    const $a = $('a', html);
    expect($a.length).toBe(1);
    expect($a.attr('href')).toBe('https://example.com/x');
    expect(html).toContain('&lt;');
    expect(html).toContain('&gt;');
    // no stray tags beyond our one anchor
    expect($('<div>' + html + '</div>').children().length).toBe(1);
  });

  it('ampersand near a mention is escaped exactly once', () => {
    const html = linkify('hi @bob & <friends> & more', opts);
    expect(html).toBe(
      'hi <a href="https://social.example/bob">@bob</a> &amp; ' +
        '&lt;friends&gt; &amp; more'
    );
    // decoding once gives back the original text
    expect($('body', html).text()).toBe(
      'hi @bob & <friends> & more'
    );
  });

  it('URL query strings keep their ampersands escaped exactly once', () => {
    const html = linkify('https://example.com/s?q=a&b=1&c=2', opts);
    const $a = $('a', html);
    expect($a.attr('href')).toBe('https://example.com/s?q=a&b=1&c=2');
    expect(html).toContain('q=a&amp;b=1&amp;c=2');
  });

  it('mixed fixture: mention, hashtag, URL, email in one post', () => {
    const html = linkify(
      '@ann loves #cats: https://cats.example/?tag=cats — mail a@b.co',
      opts
    );
    const anchors = $('a', html).toArray();
    expect(anchors.length).toBe(3);
    expect($(anchors[0]).attr('href')).toBe('https://social.example/ann');
